using System.Text.RegularExpressions;

namespace Notrelix.Application.Features.Identity.Profiles.Services;

/// <summary>
/// Server-owned object key scheme for profile photos:
/// <c>users/{userId:N}/avatar/{objectId:N}.{png|jpg|webp}</c>. The key is generated by the server,
/// carries the owner prefix, never contains client input, and is distinct from the tenant-prefixed
/// attachment keys, so each sweep recognises only its own objects. A key identifies an object; it is
/// not permission: the photo is served only through the Identity avatar read.
/// </summary>
public static class AvatarStorageKey
{
    public const string Prefix = "users/";

    /// <summary>The key path a store listing starts from (a key path has no trailing slash).</summary>
    public const string ListPath = "users";

    private static readonly Regex KeyPattern = new(
        "^users/[0-9a-f]{32}/avatar/[0-9a-f]{32}\\.(png|jpg|webp)$",
        RegexOptions.CultureInvariant | RegexOptions.NonBacktracking);

    public static string Create(Guid userId, AvatarFormat format) =>
        $"{Prefix}{userId:N}/avatar/{Guid.CreateVersion7():N}.{format.Extension}";

    /// <summary>True when <paramref name="key"/> has exactly the shape <see cref="Create"/> produces.</summary>
    public static bool IsAvatarKey(string key) => KeyPattern.IsMatch(key);

    /// <summary>Defence in depth for reads and sweeps: the key must sit under the owner's prefix.</summary>
    public static bool BelongsTo(string key, Guid userId) =>
        IsAvatarKey(key) && key.StartsWith($"{Prefix}{userId:N}/avatar/", StringComparison.Ordinal);

    public static string ContentTypeOf(string key) =>
        key.EndsWith(".png", StringComparison.Ordinal) ? "image/png"
        : key.EndsWith(".webp", StringComparison.Ordinal) ? "image/webp"
        : "image/jpeg";

    /// <summary>
    /// The address the product serves the photo from. The <c>v</c> value is the object id, so a new
    /// upload changes the address and a client or proxy may cache a given address as immutable.
    /// </summary>
    public static string UrlFor(Guid userId, string key)
    {
        var name = key[(key.LastIndexOf('/') + 1)..];
        var objectId = name[..name.IndexOf('.')];
        return $"/api/v1/users/{userId:D}/avatar?v={objectId}";
    }
}
